import{_ as a,a as r}from"./chunks/be02be44ee0ee558d010.DtZ4ricx.js";import{_ as o,C as l,o as i,c as s,j as e,a as n,E as h,a5 as c}from"./chunks/framework.DNkHA0lr.js";const x=JSON.parse('{"title":"努力工作的幻觉（以及为什么它不会让你变富）","description":"","frontmatter":{"title":"努力工作的幻觉（以及为什么它不会让你变富）","originalTitle":"The Delusion Of Hard Work (And Why It Won’t Make You Rich)","date":"2024-03-22","originalUrl":"https://thedankoe.com/letters/the-7-traits-of-the-irreplaceable-how-to-secure-your-future/","minutes":9,"sourceHash":"4b4b8d82c76e177eba4efa3b889572f2207a71757b60f206ffbdc41dfcf4ed22","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/the-7-traits-of-the-irreplaceable-how-to-secure-your-future/"}]]},"headers":[],"relativePath":"letters/the-7-traits-of-the-irreplaceable-how-to-secure-your-future.md","filePath":"letters/the-7-traits-of-the-irreplaceable-how-to-secure-your-future.md"}'),u={name:"letters/the-7-traits-of-the-irreplaceable-how-to-secure-your-future.md"};function d(f,p,b,_,m,k){const t=l("ArticleMeta");return i(),s("div",null,[p[0]||(p[0]=e("h1",{id:"努力工作的幻觉-以及为什么它不会让你变富",tabindex:"-1"},[n("努力工作的幻觉（以及为什么它不会让你变富） "),e("a",{class:"header-anchor",href:"#努力工作的幻觉-以及为什么它不会让你变富","aria-label":'Permalink to "努力工作的幻觉（以及为什么它不会让你变富）"'},"​")],-1)),h(t),p[1]||(p[1]=c('<p><a href="https://www.youtube.com/embed/h7pJO8e52IM?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>你可以在任何事情上努力工作，但这并不意味着它对人类的进步有用。</p><p>这就是努力工作的幻觉。</p><p>你可以花4年时间努力取得一个学位。</p><p>你可以花10年时间努力爬公司的阶梯。</p><p>然而，你得到的报酬，仍然远远达不到你想要的数字。</p><p>所以，你没有把自己的未来掌握在自己手中，而是选择抱怨和诉苦。</p><p>“我应该得到更多的报酬！”</p><p>“我已经努力工作了14年，这就是我得到的全部？”</p><p>“我几乎没有时间陪家人。我没有足够的钱去度假。我拼命干活，却看不到隧道尽头的光。”</p><p>这个世界上的抱怨者们，缺失了拼图中至关重要的一块：</p><p>劳动价值论认为，你应该按照你所做的工作量来获得报酬。</p><p>这让人觉得自己已经跨过了重重障碍。</p><p>这让人觉得自己理应得到些什么。</p><p>但现实并不是这样运作的。</p><p>金钱是一种价值单位。价值是衡量人们有多在乎你所做之事的标准。</p><p>你有多大价值 = 你所解决问题的规模，你所创造的解决方案带来的结果，以及你让人们关心你的创造物的能力。</p><p>如果你对自己的收入不满意，也许是时候，非常残酷诚实地审视一下，你到底为这个世界贡献了什么。</p><p>按照一个人工作量的多少来付酬，这没有道理。按照一个人所解决问题的层次来付酬，这才有道理。</p><p>为什么？</p><p>我可以努力写作一年，想成为一名作家，但一年的时间还不足以证明10万美元报酬的合理性。</p><p>你能赚到的钱，只取决于其他人有多在乎你在那一年里做了什么。也就是说，你的创造物如何让他们受益，从而帮助他们解决问题、改变生活、给人类带来进步。</p><p>抱怨自己薪水不够，不会让你得到更高的薪水。事实上，这很可能会让你被解雇或被忽视。或者，只是让你接触到的每个人都讨厌你，因为他们心里想的是：“好吧……你打算为此做点<em>什么</em>？”</p><p>唯一的选择，是把这件事掌握在自己手中。</p><h2 id="无可替代的个体" tabindex="-1">无可替代的个体 <a class="header-anchor" href="#无可替代的个体" aria-label="Permalink to &quot;无可替代的个体&quot;">​</a></h2><p><img src="'+a+'" alt=""></p><p>你之所以担心20年后什么还会有价值，是因为你的成功依赖于除你自己之外的每一个人。</p><p>成功的人不会担心，因为他们理解到底是什么让一个人成功。</p><p>收入最高的人，是这个世界上的远见者、战略家和革新者。</p><p>收入最高的人，不是那些努力工作或聪明工作的人，而是那些善用杠杆的人。</p><p>如果你想守住自己的未来，你需要具备那些能让你在任何环境中都能成功的特质。</p><p>这些特质构成了“无可替代的个体”：</p><ul><li><strong>自我实验</strong> —— 如何通过试错来解决复杂问题，并得出自己的结论。</li><li><strong>自我反思</strong> —— 如何理解自己内心的动机，从而理解他人的动机。</li><li><strong>自我发展</strong> —— 培养一种有价值的心态和技能，能够帮助他人。</li><li><strong>自我依靠</strong> —— 如何通过为自己人生的结果负责，来获得你想要的东西。</li><li><strong>自我教育</strong> —— 收集、理解并利用未知领域信息的能力。</li><li><strong>自给自足</strong> —— 维持理想生活方式并获取所需资源的能力。</li><li><strong>自我掌控</strong> —— 对驾驭现实这一过程坚定不移的投入。</li></ul><p>当你掌控了自己，你就掌控了这个世界。</p><p>如果你想变得无可替代，你就必须变得有价值。</p><p>如果你想获得高薪，你就必须让人们看到那份价值。</p><p>价值的感知方式会随着世界的变化而改变。</p><p>随着AI的到来，我们或许不知道未来的价值会以什么形式呈现，但我们知道，价值一定会存在。</p><p>人类或许不再以美元获得报酬，但仍可能以声望、地位以及任何其他能驱动人类经济运转的东西获得报酬。</p><p>以美元形式存在的货币或许不会永远持续，但从你的创造物中获利的能力会。</p><h2 id="如何守住你的未来" tabindex="-1">如何守住你的未来 <a class="header-anchor" href="#如何守住你的未来" aria-label="Permalink to &quot;如何守住你的未来&quot;">​</a></h2><p>如果没人知道或在乎你的技能，那这个技能就没有价值。</p><p>这里存在两个问题。</p><p>如果没人知道你创造了什么，那它就没有价值。</p><p>如果没人在乎你创造了什么，那它就没有价值。</p><p>在商业中，你需要一个产品，以及一群足够在乎这个产品、愿意购买它的人。</p><p>你可以把你的产品展示在网络上的人面前，但如果他们看不出它对自己生活有什么好处，他们就不会在乎它。</p><p>你可以认为自己拥有最有价值的产品，但如果你不把它展示在人们面前，他们就没有机会去在乎它。</p><p>在人际关系中，你可以把自己展示在一群潜在伴侣面前，但如果他们看不出你在他们生活中处于什么位置，他们就不会在乎你。</p><p>你可以认为自己是最有内涵、最成熟的人，但如果你整天待在家里，潜在伴侣就没有机会去在乎你。</p><h3 id="_1-成为一名创业者" tabindex="-1">1）成为一名创业者 <a class="header-anchor" href="#_1-成为一名创业者" aria-label="Permalink to &quot;1）成为一名创业者&quot;">​</a></h3><p>只有当你意识到，创业是唯一能让你完全掌控自己时间和收入的路径时，你才能真正做到这一点。</p><p>在一份工作中，你无法决定产品、无法决定自己被分配的任务，也无法决定获取客户的流程。</p><p>换句话说，你的雇主掌控着一切能让你维持生计的东西。因此，他们掌控着你的整个人生。</p><p>确实，有些工作比其他工作更宽松些，做一份临时性的工作也没什么问题，但我写这篇文章，是给那些最终想要获得自由的人看的。</p><h3 id="_2-建立分发渠道" tabindex="-1">2）建立分发渠道 <a class="header-anchor" href="#_2-建立分发渠道" aria-label="Permalink to &quot;2）建立分发渠道&quot;">​</a></h3><p>创业中有一个巨大的陷阱。</p><p>我掉进去过7次。</p><p>这就是为什么我在创业初期，7种商业模式都失败了。</p><p>我太迷恋自己正在学习的那项技能了。我只想整天搭建项目。我喜欢当那个业务的“建筑师”。</p><p>网站、落地页、logo、作品集——但我很少真正去尝试获取客户。你知道的……那些真正付钱给你的人。</p><p>当我真正开始学习如何获取客户时，用的是人工外联或付费广告。想想那种冷邮件、冷私信，还有那些我根本没钱去投的Facebook广告。</p><p>时代已经不同了。</p><p>现在，你完全有能力通过成为一家“一人媒体公司”，来积累一群潜在买家组成的受众。</p><p>每个人都在社交媒体上。那就是当下注意力所在的地方。你的客户不看电视。你的客户不听广播。你的客户不读报纸。</p><p>你的任务，就是把你的业务放到当下注意力所在的地方。这在未来或许会改变，但短期内不会。而当它真的改变时，你必须具备适应能力。</p><p>如今，通过内容——教育、启发和娱乐——来积累受众，是开启一份事业的最佳方式。</p><p>你得以在公开场合证明自己的价值，吸引一群你不需要花钱获取的追随者，然后把产品展示在他们面前，从而通过做自己想做的事情来赚钱。</p><p>去研究那些正在做你想做的事情的人。我保证，他们正在社交媒体上发帖，正在为自己建立名声，正在卖点什么东西（因为他们已经不再替别人卖东西了）。</p><h3 id="_3-学会写作" tabindex="-1">3）学会写作 <a class="header-anchor" href="#_3-学会写作" aria-label="Permalink to &quot;3）学会写作&quot;">​</a></h3><p>一个无可替代的个体所拥有的最重要的技能，就是写作。</p><p>它能一石三鸟：</p><ol><li>它通过读者反馈，教会你如何清晰表达自己的价值。</li><li>它是媒体的基础（通过让你的文字被分享，从而建立分发渠道）。</li><li>它是搭建你所构建的任何项目的晨间习惯。</li></ol><p>帖子、推文串、邮件、大纲、模块、广告、私信、书籍、视频脚本，以及其他一切，都是从写作开始的。</p><p>另一个好处是，写作是一种元技能（meta-skill）。</p><p>所谓元技能，我的意思是，你可以在没有经验的情况下开始，并在它之上层层叠加其他技能。</p><p>你不需要露脸。你不需要有英语学位。你每天都在用发短信和留言来写作。</p><p>而如果是演讲或视频，你需要剪辑技能，以及不在言语上磕磕绊绊的自信。你需要能够即时思考。</p><p>写作教会你在自己家（或咖啡馆）的舒适环境中，进行清晰的思考。</p><p>这就是为什么我推荐你从X/推特开始你的旅程。</p><p>一旦你掌握了扩大分发渠道（也就是你的受众）的方法，你就开始做一份新闻通讯，让你的影响力翻倍。然后，你构建一个文字类产品，并将其变现。</p><p>顺便说一下，在<a href="https://university.kortex.co/" target="_blank" rel="noreferrer">Kortex大学</a>里，我们会全程带着你走完这个过程，让你逐步晋级到“综合者（The Synthesizer）”、“权威者（Authority）”和“建造者（Builder）”这几个层级。</p><h3 id="_4-学会销售" tabindex="-1">4）学会销售 <a class="header-anchor" href="#_4-学会销售" aria-label="Permalink to &quot;4）学会销售&quot;">​</a></h3><p><img src="'+r+'" alt=""></p><p>销售 = 生存。</p><p>如果你不销售自己的产品，你就会被迫去销售别人的产品。</p><p>你可以整天抱怨说“现在每个人都在卖点什么东西”，但你没有理解这背后的重点。</p><p>没错，每个人都在卖点什么东西，因为他们必须这么做——如果他们（1）想要生存下去（2）想要为人类做贡献（3）想要获得回报，得到金钱。</p><p>还有一点：</p><p>人们只会投资于自己真正在乎的东西。</p><p>销售和说服是密不可分的。</p><p>如果你不学会销售，当你把产品展示在一群鸦雀无声的观众面前时，你会感到失望。</p><p>销售，就是说服人们看到你所提供之物的价值。说服，就是激励人们为自己的人生做出一个好的决定。</p><p>销售过程本身并不带有那种令人反感的油腔滑调的性质。</p><p>它是在引导人们经历一个故事，因为这就是人类建立联系、判断价值的方式。</p><ol><li>你让他们意识到一个问题。</li><li>你让他们明白，如果这个问题得不到解决，将会如何影响他们的生活。</li><li>你引入一个解决方案（也就是你的产品），它能解决这个问题。</li><li>你通过用户见证或个人经历，向他们展示改变确实是可能的证据。</li><li>给他们清晰的方向，让他们能够采取行动，并在一条新的道路上继续前行。</li></ol><p>这就是你如何撰写一个落地页、进行一场“销售”通话、给人发私信，或者——就像我在这里所做的那样——让人们阅读你的新闻通讯的方式。</p><p>如果你不喜欢销售，你或许没有意识到，你每天都在向人们“推销”你的信念、想法和世界观。</p><p>把开关从“无意识地操纵他人”，切换到“有意识地帮助他人”。</p><h3 id="_5-学会构建" tabindex="-1">5）学会构建 <a class="header-anchor" href="#_5-学会构建" aria-label="Permalink to &quot;5）学会构建&quot;">​</a></h3><blockquote><p>学会销售。学会构建。如果你能同时做到这两点，你将无可阻挡。——纳瓦尔（Naval）</p></blockquote><p>每天，抽出一个小时，去构建一个能让你理想未来变为现实的项目。</p><p>这是逃离“为别人构建项目”这一境地的唯一方式。</p><p>要构建东西，你需要具备技术层面的know-how（实操知识）。</p><p>你必须要么学会编程，要么学会使用你能获取到的现有技术。</p><p>过去需要10个人才能做的事，现在只需要1个人。</p><p>过去需要10个小时才能做的事，现在只需要1个小时。</p><p>过去需要10美元才能做的事，现在只需要1美元。</p><p>你生活在一个美好的时代，人类可以利用技术这一杠杆，去构建他们想要的东西。</p><p>网站构建工具、邮件营销软件、AI、社交媒体、课程构建工具，等等等等。</p><p>你的任务，就是通过在互联网上学习和构建，来创造并分发价值。</p><p>如果你不知道该构建什么，可以从以下几点入手：</p><ol><li>从你已经在使用的东西入手，但要把它做得更好</li><li>从你在自己生活中已经解决过的一个问题入手</li><li>构建你想在这个世界上看到的东西</li></ol><p>我们在<a href="/letters/the-future-proof-skill-stack-learn-in-this-order">上周的信中</a>讨论过这个问题。</p><p>把你的逆境变成一个好故事。把你的故事变成一个品牌。把你的旅程变成一个产品。</p><p>享受你劳动的成果，享受你今天剩下的时光。</p><p>Dan</p><hr><p><a href="/en/letters/the-7-traits-of-the-irreplaceable-how-to-secure-your-future">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',119))])}const T=o(u,[["render",d]]);export{x as __pageData,T as default};
